mapper.select:
SELECT ip.inquiry_id, ip.user_idx, u.nickname, ip.title, ip.category, ip.is_private, ip.status, ip.view_count, ip.created_at, ip.updated_at FROM INQUIRY_POST ip LEFT JOIN USERS u ON ip.user_idx = u.user_idx
AND ip.category = #{category}
AND ip.status = #{status}
AND ip.user_idx = #{userIdx}
AND (ip.title LIKE CONCAT('%', #{keyword}, '%') OR ip.content LIKE CONCAT('%', #{keyword}, '%') OR EXISTS ( SELECT 1 FROM INQUIRY_ANSWER ia WHERE ia.inquiry_id = ip.inquiry_id AND ia.content LIKE CONCAT('%', #{keyword}, '%') ))
ORDER BY ip.created_at DESC LIMIT #{pageSize} OFFSET #{offset}

SELECT COUNT(*)
FROM INQUIRY_POST ip


        AND ip.category = #{category}


        AND ip.status = #{status}


        AND ip.user_idx = #{userIdx}


        AND (ip.title   LIKE CONCAT('%', #{keyword}, '%')
        OR ip.content LIKE CONCAT('%', #{keyword}, '%')
        OR EXISTS (
        SELECT 1 FROM INQUIRY_ANSWER ia
        WHERE ia.inquiry_id = ip.inquiry_id
        AND ia.content LIKE CONCAT('%', #{keyword}, '%')
        ))

