UPDATE INQUIRY_POST
SET view_count = view_count + 1
WHERE inquiry_id = #{inquiryId}

UPDATE INQUIRY_POST
SET status = #{status}, updated_at = NOW()
WHERE inquiry_id = #{inquiryId}
